using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        var path = Path.Combine(context.TestRunResultsDirectory!, "eval-report");

        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootPath: path,
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
            ],
            chatConfiguration: GetChatConfiguration());
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.GenerateReportAsync();
        }
    }

    [TestMethod]
    public async Task GreetingResponse_IsCoherentAndRelevant()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(GreetingResponse_IsCoherentAndRelevant));

        var chatClient = scenario.ChatClient!;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello! Can you introduce yourself briefly?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task QuestionAnswering_IsRelevant()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(QuestionAnswering_IsRelevant));

        var chatClient = scenario.ChatClient!;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What are the benefits of using .NET Aspire for cloud-native applications?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task MultiTurn_MaintainsContext()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(MultiTurn_MaintainsContext));

        var chatClient = scenario.ChatClient!;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }

    private static ChatConfiguration GetChatConfiguration()
    {
        // Use the Azure OpenAI endpoint from environment or a default for local dev.
        // In CI, set AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_API_KEY environment variables.
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? "test-key";
        var modelId = Environment.GetEnvironmentVariable("AZURE_OPENAI_MODEL")
            ?? "gpt-4o-mini";

        IChatClient chatClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(apiKey))
            .GetChatClient(modelId)
            .AsIChatClient();

        return new ChatConfiguration(chatClient);
    }
}

