21.             evaluators:
22.             [
23.                 new CoherenceEvaluator(),
24.                 new RelevanceEvaluator(),
25.                 new FluencyEvaluator(),
26.             ],
27.             chatConfiguration: GetChatConfiguration());
28.     }
